  { code: 'DMS · 01', title: 'Drowsiness', trigger: 'Repeated signs of driver fatigue', states: ['Once', 'Twice', 'Third time'], response: 'Escalate from a gentle reminder to an immediate wake-up or takeover instruction.' },
  { code: 'DMS · 02', title: 'Distraction', trigger: 'Attention remains away from the driving task', states: ['Once', 'Twice', 'Third time'], response: 'Increase directness and visual salience while keeping the requested action unambiguous.' },
  { code: 'ADS · 03', title: 'Automation takeover', trigger: 'Automation becomes unavailable or unsafe to continue', states: ['Pre-warning', 'Warning', 'Emergency'], response: 'Move from preparation to explicit control transfer, with urgency encoded redundantly.' },
  { code: 'ROAD · 04', title: 'Pedestrian alert', trigger: 'A pedestrian is detected on the left or right', states: ['Left', 'Right'], response: 'Pair directional language with a spatially legible warning cue.' },
  { code: 'TRAFFIC · 05', title: 'Smart Stop & Go', trigger: 'The lead vehicle departs or traffic stops', states: ['Go', 'Stop'], response: 'Provide a low-interruption status cue that supports attention without demanding conversation.' },
  { code: 'CABIN · 06', title: 'Child lock', trigger: 'A child is detected entering or leaving the cabin', states: ['Activate', 'Deactivate'], response: 'Confirm the safety action and explain the state change in plain language.' },
]
</script>

